class Time:
    def __init__(self, nanoseconds, tz=None):
        self.nanoseconds = nanoseconds
        self.tz = tz

    @classmethod
    def from_nanoseconds(cls, nanoseconds, tz=None):
        """ Creates a Time object from nanoseconds.

        :param nanoseconds: int, the number of nanoseconds since the epoch
        :param tz: timezone, the timezone for the Time object
        :return: Time
        """
        return Time(nanoseconds, tz)

    def to_datetime(self):
        """ Converts the Time object to a datetime object.

        :return: datetime
        """
        seconds = self.nanoseconds // 1_000_000_000
        microseconds = (self.nanoseconds % 1_000_000_000) // 1_000
        dt = datetime(1970, 1, 1) + timedelta(seconds=seconds, microseconds=microseconds)
        if self.tz:
            dt = dt.replace(tzinfo=self.tz)
        return dt

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    return Time.from_nanoseconds(nanoseconds, tz)

