import time
from functools import wraps, _update_wrapper
import threading

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    class TTLCache:
        def __init__(self, maxsize: int, ttl: float, timer: Callable[[], float], typed: bool):
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.typing = hashed if typed else hash
            self.cache: Dict[Hashable, Any] = {}
            self.access_times: Dict[Hashable, float] = {}
            self.lock = threading.Lock()

        def __getitem__(self, key: Hashable) -> Any:
            now = self.timer()
            with self.lock:
                expiration = self.access_times.get(key)
                if expiration is None or expiration < now:
                    raise KeyError(key)
                return self.cache[key]

        def __setitem__(self, key: Hashable, value: Any) -> None:
            now = self.timer()
            with self.lock:
                if len(self.cache) >= self.maxsize:
                    for k, v in reversed(list(self.cache.items())):
                        if self.access_times[k] < now - self.ttl:
                            del self.cache[k]
                            del self.access_times[k]
                        else:
                            break
                self.cache[key] = value
                self.access_times[key] = now

        def __contains__(self, key: Hashable) -> bool:
            now = self.timer()
            with self.lock:
                expiration = self.access_times.get(key)
                return expiration is not None and expiration >= now

        def __delete__(self, key: Hashable) -> None:
            with self.lock:
                if key in self.cache:
                    del self.cache[key]
                    del self.access_times[key]

    def decorator(func: Callable) -> Callable:
        cache = TTLCache(maxsize, ttl, timer, typed)

        @wraps(func)
        def wrapper(*args, **kwargs):
            k = cache.typing((func, args, frozenset(kwargs.items())))
            try:
                return cache

