import functools
from collections import defaultdict

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        cache_times = defaultdict(int)
        access_count = {}
        min_access = 0

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = args if not typed else (args, tuple(kwargs.items()))
            if key in cache:
                cache_times[key] += 1
                access_count[min_access][key].remove(key)
                if not access_count[min_access][key]:
                    del access_count[min_access][key]
                min_access = min(min_access, cache_times[key])
            else:
                if len(cache) >= maxsize:
                    # Evict the least frequently used item
                    evict_key = access_count[min_access].popitem()[0]
                    del cache[evict_key]
                    del cache_times[evict_key]
                cache[key] = None
                cache_times[key] = 0
                if min_access not in access_count[key]:
                    access_count[min_access] = set()
                access_count[min_access].add(key)
                min_access = 0

            if key in cache:
                result = func(*args, **kwargs)
                cache[key] = result
            else:
                cache[key] = func(*args, **kwargs)

            return cache[key]

        return wrapper

    return decorator

