@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    def _get_traceback_info(exc_info):
        tb = exc_info[2]
        tbinfo = traceback.extract_tb(tb)
        path, line, name, src = '', '', '', None
        if tbinfo:
            path, line, name, src = tbinfo[-1]
        return {
            'file': path,
            'line': line,
            'name': name,
            'src': src
        }

    def _format_exception(e, level=0):
        if level >= max_level:
            return '...'
        exc_info = sys.exc_info()
        if not exc_info[0]:
            return str(e)

        traceback_info = _get_traceback_info(exc_info)
        formatted_exc = f"{type(e).__name__}: {e}"
        formatted_exc += f"\n  File: {traceback_info['file']}, line {traceback_info['line']}, in {traceback_info['name']}"
        if level < max_path_level:
            formatted_exc += f"\n    {traceback_info['src']}"
        return formatted_exc

    return _format_exception(e)

