def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    def is_minimum(bases):
        for base in bases:
            if any(issubclass(other, base) for other in bases if other is not base):
                return False
        return True

    while not is_minimum(classes):
        to_remove = set()
        for base in classes:
            for other in classes:
                if base is not other and issubclass(other, base):
                    to_remove.add(other)
        classes = [base for base in classes if base not in to_remove]

    return classes

