    regex_key = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*$')
    regex_value = re.compile(r'^[a-zA-Z0-9_]*$')

    for key, value in labels.items():
        key_error = None
        value_error = None

        if not isinstance(key, str) or not regex_key.match(key):
