        if isinstance(value, list):
            value_error = [{"['{0}']".format(val): 'expected string or bytes-like object'} for val in value]
        elif not isinstance(value, str) or not regex_value.match(value):
            value_error = {key: "Value does not match the regex"}

        if key_error:
            errors.append({key: key_error})
        if value_error:
            if isinstance(value_error, dict):
                errors.append(value_error)
            else:
                errors.extend(value_error)

