def check_request_type(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Public JSON payload
    try:
        data = json.loads(encode_if_text(request.body))
        if "magic_envelope" in data:
            return "public"
    except Exception:
        pass
    # Legacy XML payload
    try:
        xml = etree.fromstring(decode_if_bytes(request.body))
        if xml.tag == LEGACY_MUSIC_TAG:
            return "legacy"
    except Exception:
        pass
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return "private"
    except Exception:
        pass
    return "unknown"

