def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from lxml import etree

    try:
        # Attempt to parse JSON format
        data = json.loads(document)
        if "links" in data:
            return {
                "handle": data.get("subject", "").split("@")[0],
                "hcard_url": next((link["href"] for link in data["links"] if link["rel"] == "http://microformats.org/profile/hcard"), None)
            }
    except json.JSONDecodeError:
        # If JSON fails, try to parse XRD
        try:
            root = etree.fromstring(document)
            handle_element = root.find(".//{http://docs.oasis-open.org/ns/xrds/2005/01/xrds}Subject")
            handle = handle_element.text.split("@")[0] if handle_element is not None else None
            hcard_url_element = root.find(".//{http://docs.oasis-open.org/ns/xrds/2005/01/xrds}Link[@rel='http://microformats.org/profile/hcard']")
            hcard_url = hcard_url_element.get("template").replace("{uri}", "") if hcard_url_element is not None else None
            return {
                "handle": handle,
                "hcard_url": hcard_url
            }
        except etree.XMLSyntaxError:
            logger.warning("parse_diaspora_webfinger: could not parse document as JSON or XRD")
            return None

