def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def load_json_file(file_path):
        with open(file_path, 'r') as file:
            return json.load(file)

    def flatten_dict(d, parent_key='', sep='_'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(flatten_dict(v, new_key, sep=sep).items())
            else:
                items[new_key] = v
        return items

    spec_files = [f for f in os.listdir(plugin_dir) if f.endswith('.spec.json')]
    spec_dict = {}
    for file_name in spec_files:
        file_path = os.path.join(plugin_dir, file_name)
        spec_dict.update(load_json_file(file_path))

    return flatten_dict(spec_dict)

